module card_game(\n    input clk,\n    input rst_n,\n    input start,\n    input [7:0] n,\n    input [7:0] m,\n    input [15:0] jiro_strength [0:99],\n    input [99:0] jiro_type,\n    input [15:0] ciel_strength [0:99],\n    output reg [15:0] result,\n    output reg done\n);\n\n    localparam [3:0]\n        IDLE              = 4'd0,\n        READ_N_M          = 4'd1,\n        READ_JIRO         = 4'd2,\n        READ_CIEL         = 4'd3,\n        SEPARATE          = 4'd4,\n        SORT_DEF          = 4'd5,\n        SORT_ATK          = 4'd6,\n        SORT_CIEL         = 4'd7,\n        COMPUTE_TOTAL_CIEL= 4'd8,\n        POSS1_DEF         = 4'd9,\n        POSS1_ATK         = 4'd10,\n        POSS2             = 4'd11,\n        COMPUTE_RESULT    = 4'd12,\n        DONE              = 4'd13;\n\n    reg [3:0] state;\n    reg [7:0] i, j, k;\n    reg [15:0] def_list [0:99];\n    reg [15:0] atk_list [0:99];\n    reg [15:0] ciel_sorted [0:99];\n    reg [99:0] used;\n    reg [15:0] total_ciel;\n    reg [15:0] sum_def_used;\n    reg [15:0] damage1, damage2;\n    reg [7:0] num_def, num_atk;\n    reg [15:0] temp;\n    reg found;\n    reg [15:0] sum_c, sum_a;\n    reg [7:0] cycles;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            result <= 16'd0;\n            i <= 8'd0;\n            j <= 8'd0;\n            k <= 8'd0;\n            damage1 <= 16'd0;\n            damage2 <= 16'd0;\n            sum_def_used <= 16'd0;\n            total_ciel <= 16'd0;\n            num_def <= 8'd0;\n            num_atk <= 8'd0;\n            sum_c <= 16'd0;\n            sum_a <= 16'd0;\n            used <= 100'd0;\n            cycles <= 8'd0;\n            temp <= 16'd0;\n            for (i = 8'd0; i < 8'd100; i = i + 1) begin\n                def_list[i] <= 16'd0;\n                atk_list[i] <= 16'd0;\n                ciel_sorted[i] <= 16'd0;\n            end\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    cycles <= 8'd0;\n                    if (start) state <= READ_N_M;\n                end\n                \n                READ_N_M: begin\n                    state <= READ_JIRO;\n                    i <= 8'd0;\n                    num_def <= 8'd0;\n                    num_atk <= 8'd0;\n                end\n\n                READ_JIRO: begin\n                    if (i < n) begin\n                        if (!jiro_type[i]) begin\n                            def_list[num_def] <= jiro_strength[i];\n                            num_def <= num_def + 8'd1;\n                        end else begin\n                            atk_list[num_atk] <= jiro_strength[i];\n                            num_atk <= num_atk + 8'd1;\n                        end\n                        i <= i + 8'd1;\n                    end else begin\n                        i <= 8'd0;\n                        state <= READ_CIEL;\n                    end\n                end\n\n                READ_CIEL: begin\n                    if (i < m) begin\n                        ciel_sorted[i] <= ciel_strength[i];\n                        i <= i + 8'd1;\n                    end else begin\n                        i <= 8'd0;\n                        state <= SEPARATE;\n                    end\n                end\n\n                SEPARATE: state <= SORT_DEF;\n\n                SORT_DEF: begin\n                    if (i < num_def) begin\n                        if (j < num_def - 8'd1) begin\n                            if (def_list[j] > def_list[j + 8'd1]) begin\n                                temp <= def_list[j];\n                                def_list[j] <= def_list[j + 8'd1];\n                                def_list[j + 8'd1] <= temp;\n                            end\n                            j <= j + 8'd1;\n                        end else begin\n                            j <= 8'd0;\n                            i <= i + 8'd1;\n                        end\n                    end else begin\n                        i <= 8'd0;\n                        j <= 8'd0;\n                        state <= SORT_ATK;\n                    end\n                end\n\n                SORT_ATK: begin\n                    if (i < num_atk) begin\n                        if (j < num_atk - 8'd1) begin\n                            if (atk_list[j] > atk_list[j + 8'd1]) begin\n                                temp <= atk_list[j];\n                                atk_list[j] <= atk_list[j + 8'd1];\n                                atk_list[j + 8'd1] <= temp;\n                            end\n                            j <= j + 8'd1;\n                        end else begin\n                            j <= 8'd0;\n                            i <= i + 8'd1;\n                        end\n                    end else begin\n                        i <= 8'd0;\n                        j <= 8'd0;\n                        state <= SORT_CIEL;\n                    end\n                end\n\n                SORT_CIEL: begin\n                    if (i < m) begin\n                        if (j < m - 8'd1) begin\n                            if (ciel_sorted[j] > ciel_sorted[j + 8'd1]) begin\n                                temp <= ciel_sorted[j];\n                                ciel_sorted[j] <= ciel_sorted[j + 8'd1];\n                                ciel_sorted[j + 8'd1] <= temp;\n                            end\n                            j <= j + 8'd1;\n                        end else begin\n                            j <= 8'd0;\n                            i <= i + 8'd1;\n                        end\n                    end else begin\n                        i <= 8'd0;\n                        j <= 8'd0;\n                        state <= COMPUTE_TOTAL_CIEL;\n                    end\n                end\n\n                COMPUTE_TOTAL_CIEL: begin\n                    if (i < m) begin\n                        total_ciel <= total_ciel + ciel_sorted[i];\n                        i <= i + 8'd1;\n                    end else begin\n                        i <= 8'd0;\n                        state <= POSS1_DEF;\n                        sum_def_used <= 16'd0;\n                        used <= 100'd0;\n                    end\n                end\n\n                POSS1_DEF: begin\n                    if (i < num_def) begin\n                        found <= 1'b0;\n                        if (j < m) begin\n                            if (!used[j] && ciel_sorted[j] > def_list[i]) begin\n                                used[j] <= 1'b1;\n                                sum_def_used <= sum_def_used + ciel_sorted[j];\n                                found <= 1'b1;\n                            end\n                            j <= j + 8'd1;\n                        end else begin\n                            if (!found) begin\n                                damage1 <= 16'd0;\n                                i <= num_def; // Break loop\n                                state <= POSS2;\n                            end else begin\n                                i <= i + 8'd1;\n                                j <= 8'd0;\n                            end\n                        end\n                    end else begin\n                        i <= 8'd0;\n                        j <= 8'd0;\n                        state <= POSS1_ATK;\n                    end\n                end\n\n                POSS1_ATK: begin\n                    if (i < num_atk) begin\n                        found <= 1'b0;\n                        if (j < m) begin\n                            if (!used[j] && ciel_sorted[j] >= atk_list[i]) begin\n                                used[j] <= 1'b1;\n                                found <= 1'b1;\n                            end\n                            j <= j + 8'd1;\n                        end else begin\n                            if (!found) begin\n                                damage1 <= 16'd0;\n                                state <= POSS2;\n                            end else begin\n                                i <= i + 8'd1;\n                                j <= 8'd0;\n                            end\n                        end\n                    end else begin\n                        state <= COMPUTE_RESULT;\n                        temp <= 16'd0;\n                        i <= 8'd0;\n                        j <= 8'd0;\n                    end\n                end\n\n                POSS2: begin\n                    if (i < num_atk && i < m) begin\n                        if (ciel_sorted[m - 8'd1 - i] >= atk_list[i]) begin\n                            sum_c <= sum_c + ciel_sorted[m - 8'd1 - i];\n                            sum_a <= sum_a + atk_list[i];\n                            damage2 <= sum_c + ciel_sorted[m - 8'd1 - i] - sum_a - atk_list[i];\n                            i <= i + 8'd1;\n                        end else begin\n                            i <= 8'd0;\n                            state <= COMPUTE_RESULT;\n                        end\n                    end else begin\n                        i <= 8'd0;\n                        state <= COMPUTE_RESULT;\n                    end\n                end\n\n                COMPUTE_RESULT: begin\n                    if (i == 8'd0) begin\n                        i <= 8'd1;\n                        temp <= 16'd0;\n                        j <= 8'd0;\n                    end else if (i == 8'd1) begin\n                        if (j < num_atk) begin\n                            temp <= temp + atk_list[j];\n                            j <= j + 8'd1;\n                        end else begin\n                            damage1 <= total_ciel - sum_def_used - temp;\n                            i <= 8'd2;\n                        end\n                    end else if (i == 8'd2) begin\n                        result <= (damage1 > damage2) ? damage1 : damage2;\n                        state <= DONE;\n                    end\n                end\n\n                DONE: begin\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n\n                default: state <= IDLE;\n            endcase\n            \n            // Cycle counter timeout\n            cycles <= cycles + 8'd1;\n            if (cycles == 8'd200) state <= COMPUTE_RESULT;\n        end\n    end\n\nendmodule